r,jdbcType=VARCHAR} CREATE_USER, #{item.createDept,jdbcType=VARCHAR} CREATE_DEPT, sysdate CREATE_TIME, #{item.updateUser,jdbcType=VARCHAR} UPDATE_USER, sysdate UPDATE_TIME, #{item.hsType,jdbcType=VARCHAR} HS_TYPE, #{item.isFinLicence,jdbcType=VARCHAR} IS_FIN_LICENCE, #{item.industry3,jdbcType=VARCHAR} INDUSTRY3, #{item.industry4,jdbcType=VARCHAR} INDUSTRY4, #{item.customerId,jdbcType=VARCHAR} CUSTOMER_ID, #{item.orgType,jdbcType=VARCHAR} ORG_TYPE, #{item.isShareholderRelated,jdbcType=VARCHAR} IS_SHAREHOLDER_RELATED FROM DUAL ) TEMP
