WHEN NOT MATCHED THEN INSERT (CUSTOMER_ID, PARTY_TYPE3, PARTY_TYPE2, PARTY_TYPE1, INDUSTRY, INDUSTRY2, INSITITUTE_CODE, IS_GOV, MAIN_CAPITAL, REGISTER_CAPITAL, PROVINCE, CITY, COUNTY, HOLDING_TYPE, CUSTOMER_OBJ_TYPE, IS_LISTED_COMPANY, IS_GROUP_CUSTOMER, PARENT_CUSTOMER_ID, PARENT_CUSTOMER_NAME, IS_PRIVATE, IS_ESCAPE_DEPT, CREDIT_TYPE, IS_CREDIT_RELATED_TRD, STRUCT_ADJUST_TYPE, INDUS_UPGRATE_TYPE, BUSI_SCOPE, MAIN_BUSI, SEX, PERSON_ID, M_PHONE, PHONE, POSITION, COMPANY_NAME, ADDRESS, MAIL, PROPERTY, COMPANY_NATURE, LINK_ID1, LINK_ID2, LINK_ID3, REMARK, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME, HS_TYPE, IS_FIN_LICENCE, INDUSTRY3, INDUSTRY4, ORG_TYPE, IS_SHAREHOLDER_RELATED) values (TEMP.CUSTOMER_ID, TEMP.PARTY_TYPE3, TEMP.PARTY_TYPE2, TEMP.PARTY_TYPE1, TEMP.INDUSTRY, TEMP.INDUSTRY2, TEMP.INSITITUTE_CODE, TEMP.IS_GOV, TEMP.MAIN_CAPITAL, TEMP.REGISTER_CAPITAL, TEMP.PROVINCE, TEMP.CITY, TEMP.COUNTY, TEMP.HOLDING_TYPE, TEMP.CUSTOMER_OBJ_TYPE, TEMP.IS_LISTED_COMPANY, TEMP.IS_GROUP_CUSTOMER, TEMP.PARENT_CUSTOMER_ID, TEMP.PARENT_CUSTOMER_NAME, TEMP.IS_PRIVATE, TEMP.IS_ESCAPE_DEPT, TEMP.CREDIT_TYPE, TEMP.IS_CREDIT_RELATED_TRD, TEMP.STRUCT_ADJUST_TYPE, TEMP.INDUS_UPGRATE_TYPE,TEMP.BUSI_SCOPE,TEMP.MAIN_BUSI, TEMP.SEX, TEMP.PERSON_ID, TEMP.M_PHONE, TEMP.PHONE, TEMP.POSITION, TEMP.COMPANY_NAME, TEMP.ADDRESS, TEMP.MAIL, TEMP.PROPERTY, TEMP.COMPANY_NATURE, TEMP.LINK_ID1, TEMP.LINK_ID2, TEMP.LINK_ID3, TEMP.REMARK, TEMP.CREATE_USER, TEMP.CREATE_DEPT, TEMP.CREATE_TIME, TEMP.UPDATE_USER, TEMP.UPDATE_TIME, TEMP.HS_TYPE, TEMP.IS_FIN_LICENCE, TEMP.INDUSTRY3, TEMP.INDUSTRY4, TEMP.ORG_TYPE, TEMP.IS_SHAREHOLDER_RELATED);
